using System;
using System.IO;
using System.Collections.Generic;
using System.Runtime.Serialization;
[DataContract] sealed class WorldBuildings { [DataMember] public int Seed;[DataMember] public List<BuildPiece> Pieces=new List<BuildPiece>(); }
[DataContract] sealed class ExpeditionGameSave {
 [DataMember] public int Format=1,Seed=431;[DataMember] public double X=ExpeditionWorld.SpawnX,Z=ExpeditionWorld.SpawnZ;
 [DataMember] public ExpeditionLootSave Profile=new ExpeditionLootSave();[DataMember] public List<WorldBuildings> Buildings=new List<WorldBuildings>();
}
sealed partial class ExpeditionGame {
 public bool NoDiskSave;public ExpeditionGameSave GuestOriginal;public ExpeditionGameSave Save;public ExpeditionWorld World;public ExpeditionBuilding Building;public string PathName;public bool Healthy=true;public string Notice="";public double Clock,LastDamage=-100,Stamina=100,Shield=4;
 public ExpeditionLootSave Profile{get{return Save.Profile;}}public ExpeditionCraftState Craft{get{return Profile.Crafting;}}public ExpeditionLife Life{get{return Profile.Life;}}public ExpeditionSurvivor Skills{get{return Profile.Survivor;}}
 public ExpeditionGame(string path,int seed=431){PathName=path;Save=new ExpeditionGameSave{Seed=seed};if(File.Exists(path))try{Save=Json.Read<ExpeditionGameSave>(File.ReadAllText(path));if(Save==null||Save.Format!=1||Save.Profile==null)throw new IOException("Unsupported profile format");}catch(Exception ex){Healthy=false;Notice="SAVE PROTECTED / "+ex.Message;}try{Normalize();}catch(Exception ex){Healthy=false;Notice="SAVE PROTECTED / "+ex.Message;Save=new ExpeditionGameSave{Seed=seed};Normalize();}}
 public void Normalize(){if(Save.Profile==null)Save.Profile=new ExpeditionLootSave();if(Profile.Crafting==null)Profile.Crafting=new ExpeditionCraftState();if(Profile.Survivor==null)Profile.Survivor=new ExpeditionSurvivor();if(Profile.Life==null)Profile.Life=new ExpeditionLife();if(Profile.Items==null)Profile.Items=new List<ExpeditionRelic>();if(Profile.Claimed==null)Profile.Claimed=new List<string>();if(Profile.Journal==null)Profile.Journal=new ExpeditionJournal();if(Profile.Journal.Seen==null)Profile.Journal.Seen=new List<string>();if(Profile.Worlds==null)Profile.Worlds=new List<ExpeditionWorldChanges>();if(Save.Buildings==null)Save.Buildings=new List<WorldBuildings>();Craft.Normalize();Skills.Normalize();Life.Normalize();ResearchNormalize();World=new ExpeditionWorld(Save.Seed);World.Changes=Profile.Worlds.Find(w=>w.Seed==Save.Seed&&w.Version=="south-block-1");if(World.Changes==null){World.Changes=new ExpeditionWorldChanges{Seed=Save.Seed};Profile.Worlds.Add(World.Changes);}World.Changes.Index();var b=Save.Buildings.Find(w=>w.Seed==Save.Seed);if(b==null){b=new WorldBuildings{Seed=Save.Seed};Save.Buildings.Add(b);}World.Changes.UpgradeTerrain(b.Pieces,Life.Camps);Building=new ExpeditionBuilding(World.Height);foreach(var piece in b.Pieces)if(piece==null||piece.Kind<0||piece.Kind>=BuildDefinition.All.Length||!double.IsFinite(piece.X+piece.Y+piece.Z+piece.Yaw))throw new IOException("Invalid building data");Building.Pieces=b.Pieces;foreach(var piece in Building.Pieces){if(string.IsNullOrEmpty(piece.Id))piece.Id=Guid.NewGuid().ToString("N");if(piece.Health<0)piece.Health=piece.Def.Durability;if(piece.Stock==null)piece.Stock=new int[15];else if(piece.Stock.Length!=15)Array.Resize(ref piece.Stock,15);}if(!Building.Evaluate(Building.Pieces).Valid)throw new IOException("Unsupported saved structures");LivingNormalize();if(!World.Playable(Save.X,Save.Z)){Save.X=ExpeditionWorld.SpawnX;Save.Z=ExpeditionWorld.SpawnZ;}}
 public bool Persist(){Craft.CommitAmmo();if(NoDiskSave)return true;if(!Healthy){Notice="Save unavailable; changes disabled to protect existing data.";return false;}try{Save.Buildings.Find(w=>w.Seed==Save.Seed).Pieces=Building.Pieces;Directory.CreateDirectory(System.IO.Path.GetDirectoryName(PathName));string temp=PathName+".tmp";var disk=Save;if(GuestOriginal!=null){disk=Json.Read<ExpeditionGameSave>(Json.Write(Save));disk.Seed=GuestOriginal.Seed;disk.X=GuestOriginal.X;disk.Z=GuestOriginal.Z;disk.Buildings=GuestOriginal.Buildings;disk.Profile.Worlds=GuestOriginal.Profile.Worlds;disk.Profile.Crafting.Gathered=GuestOriginal.Profile.Crafting.Gathered;disk.Profile.Survivor.Defeated=GuestOriginal.Profile.Survivor.Defeated;disk.Profile.Claimed=GuestOriginal.Profile.Claimed;}File.WriteAllText(temp,Json.Write(disk));if(File.Exists(PathName))File.Replace(temp,PathName,PathName+".bak");else File.Move(temp,PathName);return true;}catch(Exception e){Notice="SAVE FAILED / "+e.Message;return false;}}
 public bool Change(Action action){if(!Healthy){Notice="Save protected; repair or import a valid profile.";return false;}Craft.CommitAmmo();string before=Json.Write(Save);try{action();if(Persist())return true;}catch(Exception ex){Notice="CHANGE FAILED / "+ex.Message;}Save=Json.Read<ExpeditionGameSave>(before);Normalize();return false;}
 public double Hour{get{return (6+World.Changes.Time/150)%24;}}public bool Night{get{return Hour>=20||Hour<6;}}
 public double MaxHealth{get{return 100+GearVitality+Talent("health")*10;}}
 public double MaxStamina{get{return 100+Talent("stamina")*10+(Skills.Stamina.Level-1)*5+(Skills.Agility.Level-1)*2;}}
 public bool CanSprint{get{return Stamina>6&&Life.Energy>10&&Life.Hydration>5&&Life.Hunger>5;}}
 public double Speed{get{return ConditionSpeed*(Life.Hydration<20||Life.Hunger<20?.8:1)*(1+Math.Min(20,Skills.Agility.Level-1)*.005)*(1+Talent("speed")*.03);}}
 public bool Tick(double dt,bool sprint){Clock+=dt;Life.RecoveryBoost=Math.Max(0,Life.RecoveryBoost-dt);World.Changes.Time+=dt;Shield=Math.Max(0,Shield-dt);Life.TravelCooldown=Math.Max(0,Life.TravelCooldown-dt);Life.Hunger=Math.Max(0,Life.Hunger-dt/90*(1-Talent("hunger")*.08));Life.Hydration=Math.Max(0,Life.Hydration-dt/60*(1-Talent("water")*.08));Life.Energy=Math.Max(0,Life.Energy-dt/150*(Life.SurvivalTech.Contains(4)?.75:1)*(1-Talent("fatigue")*.08));if(sprint&&CanSprint){Stamina=Math.Max(0,Stamina-dt*18*(1-Talent("sprint")*.08));Skills.Stamina.Gain(dt*2);Skills.Agility.Gain(dt*2);Life.Hydration=Math.Max(0,Life.Hydration-dt/120*(1-Talent("water")*.08));}else if(!Handling.HoldingBreath)Stamina=Math.Min(MaxStamina,Stamina+dt*(Life.Sickness>0?.75:1)*(Life.Morale>75?1.15:1)*(Life.Hunger>75&&Life.Hydration>75?1.1:1)*(Life.Energy<20||Life.Hydration<20?6:15)*(1+Talent("breath")*.10));return TickConditions(dt);}
 public void Hurt(int tier,bool bite=true){if(Shield>0)return;Life.Health-=Math.Max(3,(7+tier*3)*100.0/(100+GearArmor+Talent("armor")*8)*(1-Talent("guard")*.05)*(Life.Health<MaxHealth*.30&&Talent("resolve")>0?.8:1));LastDamage=Clock;if(bite)Life.Wounds.Add(new ExpeditionWound());Notice="WOUNDED / bleeding drains health / H to bandage";}
 public void Die(Func<ExpeditionBag,bool> safe){Handling.HoldingBreath=false;Handling.Bloom=Handling.RecoilX=Handling.RecoilY=0;NoiseLevel=0;Sneaking=false;Skills.Die();Life.Wounds.Clear();Life.Sickness=0;Life.Trauma=600;Life.Morale=Math.Max(10,Life.Morale-15);Life.Food=Math.Max(0,Life.Food-1);Life.Hunger=Life.Hydration=Life.Energy=70;Life.Health=MaxHealth*.7;Stamina=MaxStamina;Shield=10;var b=Life.Camps.Find(c=>c.Id==Life.Respawn&&c.Seed==Save.Seed);Save.X=b!=null&&safe(b)?b.X:ExpeditionWorld.SpawnX;Save.Z=b!=null&&safe(b)?b.Z:ExpeditionWorld.SpawnZ;Persist();Notice="DIED / partial skill XP cleared; levels, research and gear kept; trauma lowers recovery for 10 minutes.";}
 public string RecipeReason(ExpeditionRecipe r){if(r.Kind=="survival-tech"&&Life.SurvivalTech.Contains(r.Result))return "Already crafted";if(r.Kind=="weapon"&&r.Result==27&&!Craft.Weapons.Contains(17))return "Craft a chainsaw first";if(r.Kind=="legendary"&&LegendaryReason!="Ready")return LegendaryReason;if(r.Kind=="tool"&&Craft.HasAxe)return "Already owned";if(r.Kind=="attachment"&&!IsGun(Craft.Weapon))return "This tuning kit fits guns only";if(r.Kind=="weapon"&&WeaponGate(r.Result)!="Ready")return WeaponGate(r.Result);if(!Knows(r))return "Research blueprint first ("+ResearchCost(r)+" RP)";if(r.Kind=="mill"&&Life.MillCores<1)return "Requires a Foreman core from the lumber mill boss";if(r.Kind=="mill"&&Life.WeaponQuality[Craft.Weapon]>=20)return "Already tempered";if(r.Kind=="attachment"&&Life.WeaponQuality[Craft.Weapon]>=r.Result)return "Already fitted";if(r.Kind=="bench"&&Craft.BenchTier>=r.Result)return "Already upgraded";if(r.Kind=="weapon"&&Craft.Weapons.Contains(r.Result))return "Already owned";if(r.Kind=="night"&&(Life.NightEssence<8||Skills.Crafting.Level<2))return "Needs 8 night catalysts and Crafting 2";if(r.Kind=="night"&&Life.WeaponQuality[Craft.Weapon]>=25)return "Already tuned";if(r.Kind=="weapon"&&r.Tier>=3&&Skills.Crafting.Level<r.Tier-1)return "Needs Crafting "+(r.Tier-1);if(Craft.UnlockedTier<r.Tier)return "Discover tier "+r.Tier+" materials";if(Craft.BenchTier<r.Station)return "Needs workshop "+r.Station;for(int i=0;i<7;i++)if(Craft.Materials[i]<r.Cost[i])return "Missing "+ResourceNames[i];return "Ready";}
 public string CraftRecipe(ExpeditionRecipe r){if(r.Kind=="build")return Notice="Select this blueprint in the building catalogue";var why=RecipeReason(r);if(why!="Ready")return Notice=why;bool ok=Change(()=>{Craft.Spend(r);switch(r.Kind){case "bench":Craft.BenchTier=r.Result;AwardResearch("milestone/workshop/"+r.Tier,8);break;case "weapon":Craft.Weapons.Add(r.Result);Equip(r.Result);break;case "armor":var plate=new ExpeditionRelic{Id="crafted/"+Guid.NewGuid(),Name=r.Name,Origin="Player workshop",Slot=r.Result==11?"head":r.Result==12?"hands":r.Result==13?"feet":"chest",Level=r.Tier,Armor=r.Result>=11?r.Tier*3:r.Tier*10+2,Vitality=r.Result>=11?r.Tier:r.Tier*3};Profile.Items.Add(plate);EquipGear(plate.Id);break;case "legendary":Life.LegendaryCores--;Life.WeaponQuality[Craft.Weapon]=50;break;case "mill":Life.MillCores--;Life.WeaponQuality[Craft.Weapon]=Math.Max(20,Life.WeaponQuality[Craft.Weapon]);break;case "attachment":Life.WeaponQuality[Craft.Weapon]=Math.Max(Life.WeaponQuality[Craft.Weapon],r.Result);break;case "tool":Craft.HasAxe=true;break;case "fuel":Craft.Fuel+=r.Result;break;case "arrow":Craft.Arrows+=r.Result;break;case "medicine":Life.Medicine+=r.Result*(Life.SurvivalTech.Contains(3)?2:1);break;case "survival-tech":if(!Life.SurvivalTech.Contains(r.Result))Life.SurvivalTech.Add(r.Result);break;case "ammo":Craft.GiveAmmo(0,r.Result);break;case "ammo-rifle":Craft.GiveAmmo(1,r.Result);break;case "ammo-carbine":Craft.GiveAmmo(2,r.Result);break;case "ammo-shell":Craft.GiveAmmo(3,r.Result);break;case "ammo-cell":Craft.GiveAmmo(4,r.Result);break;case "bandage":Life.Bandages+=r.Result;break;case "food":Life.Food+=r.Result;break;case "bag":Life.Bags+=r.Result;break;case "night":Life.NightEssence-=8;Life.WeaponQuality[Craft.Weapon]=25;break;}Skills.Crafting.Gain(r.Tier*12);Career.Gain(r.Tier*12);});return Notice=ok?"Crafted "+r.Name:Notice;}
 public void Equip(int id){if(!Craft.Weapons.Contains(id)||id==Craft.Weapon)return;if(WeaponGate(id)!="Ready"){Notice=WeaponGate(id);return;}Craft.CommitAmmo();Craft.Weapon=id;Craft.LoadAmmo();Handling.Weapon=-1;}
 public static int GunTier(int id)=>id>=22?(id==22?1:id<=24?2:id==25?3:id==26?4:5):id>=8?(id<=13?1:id<=16?2:id==17?3:id==18?3:id==19?4:id==20?3:4):id==6?2:id==7?3:Math.Max(2,Math.Clamp(id,1,5)); public int Magazine{get{return Craft.Weapon==6?1:Craft.Weapon==7?2:Craft.Weapon==0?12:Craft.Weapon==3?24:6;}}
 public void Reload(){if(!IsGun(Craft.Weapon)||WeaponGate(Craft.Weapon)!="Ready")return;int n=Math.Min(Craft.Reserve,Math.Max(0,Magazine-Craft.Ammo));Craft.Reserve-=n;Craft.Ammo+=n;}
 public double Damage(bool head)=>DamageFor(Craft.Weapon,head); public double DamageFor(int weapon,bool head){double d=IsMelee(weapon)?(weapon==22?20:weapon==23?32:weapon==24?44:weapon==25?58:weapon==26?78:weapon==27?36:weapon==8?12:weapon==9?16:weapon==10?24:weapon==11?30:weapon==13?32:weapon==14?34:weapon==15?28:weapon==16?42:weapon==17?18:weapon==20?48:65):IsBow(weapon)?(weapon==12?26:weapon==18?48:weapon==19?62:38):weapon==7?14:weapon==0?28:weapon==3?30:52;return d*(1+Math.Max(0,GunTier(weapon)-1)*.2)*(1+(ProficiencyFor(weapon).Level-1)*.01)*(1+Life.WeaponQuality[weapon]/100.0)*(1+Talent("damage")*.04)*(IsMelee(weapon)?1+Talent("melee")*.15:1)*(head?2*(1+Talent("headshot")*.08):1);}
 public void Kill(string id,int tier,int night,bool train=true){if(Profile.Survivor.Defeated.Contains(id))return;Profile.Survivor.Defeated.Add(id);if(train)TrainWeapon(18);Career.Gain(20+tier*8);if(night>0){Life.NightEssence+=night;Life.Food++;AwardResearch("milestone/night-expedition",10);}uint roll=World.Hash(id.GetHashCodeStable(),tier);if(tier>=2&&GunsUnlocked&&roll%5==0){int gun=Math.Clamp(tier,0,5);if(!Craft.Weapons.Contains(gun))Craft.Weapons.Add(gun);Life.WeaponQuality[gun]=Math.Max(Life.WeaponQuality[gun],5+tier*2);Notice="Looted "+GunNames[gun];}else if(roll%3==0){Life.Food++;Craft.GiveAmmo((int)(roll%(tier>=5?5u:tier>=3?4u:2u)),6);}Persist();}
 public bool Gather(string id,int material,int tier,int amount){if(Craft.Gathered.Contains(id))return false;return Change(()=>{Craft.Gathered.Add(id);Craft.Materials[material]+=amount+Talent("harvest");Career.Gain(10);Craft.UnlockedTier=Math.Max(Craft.UnlockedTier,tier);Skills.Survival.Gain(15);AwardResearch("zone/"+tier,10+tier*5);if(World.Hash(id.GetHashCodeStable(),material)%(uint)Math.Max(2,5-Skills.Survival.Level/5)==0)Life.Food++;Notice="Gathered "+(amount+Talent("harvest"))+" "+ResourceNames[material];});}
 public string AddBag(double x,double z,Func<ExpeditionBag,bool> safe){if(Life.Bags<1)return Notice="Craft a tier 2 sleeping bag kit first (K)";var b=new ExpeditionBag{Id=Guid.NewGuid().ToString(),Seed=Save.Seed,X=x,Z=z};if(!safe(b))return Notice="Camp is obstructed or enemies are nearby";Change(()=>{Life.Bags--;Life.Camps.Add(b);Life.Respawn=b.Id;AwardResearch("milestone/camp",8);});return Notice="Sleeping bag placed and bound";}
 public string Travel(ExpeditionBag b,Func<ExpeditionBag,bool> safe){var a=Life.Camps.Find(c=>c.Seed==Save.Seed&&Distance(c.X,c.Z,Save.X,Save.Z)<4);if(a==null||b.Seed!=Save.Seed)return Notice="Stand within 4m of a bag in this world";if(a.Id==b.Id)return Notice="Already at camp";if(Night)return Notice="Travel is daylight only";if(Life.TravelCooldown>0)return Notice="Travel cooldown: "+(int)Math.Ceiling(Life.TravelCooldown/60)+" min";if(Life.Wounds.Count>0)return Notice="Heal all wounds first";if(Life.Food<1||Craft.Water<1||Life.Energy<(Talent("travel")>0?15:25))return Notice="Needs food, water and "+(Talent("travel")>0?15:25)+" energy";if(!safe(a)||!safe(b))return Notice="Camp is unsafe";return Notice=Change(()=>{Life.Food--;Craft.Water--;Life.Energy-=Talent("travel")>0?15:25;Life.TravelCooldown=Talent("travel")>0?420:600;Save.X=b.X;Save.Z=b.Z;})?"Travelled":"Travel save failed";}
 public bool ImportLegacy(string profilePath,string structuresDirectory){if(!Healthy)return false;var old=Json.Read<ExpeditionLootSave>(File.ReadAllText(profilePath));if(old==null||old.Crafting==null||old.Survivor==null)throw new IOException("Not an Expedition loot profile");Craft.CommitAmmo();string before=Json.Write(Save);try{Save.Profile=old;Save.X=ExpeditionWorld.SpawnX;Save.Z=ExpeditionWorld.SpawnZ;Save.Buildings=new List<WorldBuildings>();if(Directory.Exists(structuresDirectory))foreach(string p in Directory.GetFiles(structuresDirectory,"south-block-1-*-buildings.json")){string seed=System.IO.Path.GetFileName(p).Replace("south-block-1-","").Replace("-buildings.json","");int s;if(int.TryParse(seed,out s))Save.Buildings.Add(new WorldBuildings{Seed=s,Pieces=Json.Read<List<BuildPiece>>(File.ReadAllText(p))});}Normalize();if(!Persist())throw new IOException(Notice);Notice="Imported legacy character, world edits and structures";return true;}catch{Save=Json.Read<ExpeditionGameSave>(before);Normalize();throw;}}
 public static double Distance(double x,double z,double xx,double zz){return Math.Sqrt((x-xx)*(x-xx)+(z-zz)*(z-zz));}
 public static readonly string[] ResourceNames={"Timber","Stone","Fiber","Forest resin","Alloy scrap","Electronics","Bioalloy"};
 public static readonly string[] GunNames={"Trail pistol","Trail rifle","Woodland rifle","Industrial carbine","Precision rifle","Experimental rifle","Woodland bow","Scrap shotgun","Sturdy stick","Hand stone","Wooden club","Stone spear","Simple bow","Baseball bat","Claw hammer","Iron rod","Iron spear","Chainsaw","Recurve bow","Crossbow","Machete","Sledgehammer","Stone knife","Hunting knife","Scrap sword","Forged sword","Alloy longsword","Stormfire chain sword"};
}
